package main

import (
	"encoding/json"
	"log"
	"net/url"
	"strings"

	"github.com/PuerkitoBio/goquery"
	"github.com/valyala/fasthttp"
)

type FetchRequest struct {
	URL string `json:"url"`
}

type FetchResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
	Error       string `json:"error,omitempty"`
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Set response content type
	ctx.SetContentType("application/json")

	// Parse request body
	var req FetchRequest
	if err := json.Unmarshal(ctx.PostBody(), &req); err != nil {
		resp := FetchResponse{Error: "invalid request body: " + err.Error()}
		body, _ := json.Marshal(resp)
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBody(body)
		return
	}

	// Validate URL
	if req.URL == "" {
		resp := FetchResponse{Error: "url field is required"}
		body, _ := json.Marshal(resp)
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBody(body)
		return
	}

	// Parse and validate URL
	parsedURL, err := url.Parse(req.URL)
	if err != nil || (parsedURL.Scheme != "http" && parsedURL.Scheme != "https") {
		resp := FetchResponse{Error: "invalid URL"}
		body, _ := json.Marshal(resp)
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBody(body)
		return
	}

	// Create fasthttp client with DialDualStack
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	// Prepare request
	req2 := fasthttp.AcquireRequest()
	resp2 := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(req2)
	defer fasthttp.ReleaseResponse(resp2)

	req2.SetRequestURI(req.URL)
	req2.Header.SetMethod("GET")
	req2.Header.Set("User-Agent", "Mozilla/5.0 (compatible; FetchPreview/1.0)")

	// Fetch URL with redirects
	err = client.DoRedirects(req2, resp2, 10)
	if err != nil {
		resp := FetchResponse{Error: "failed to fetch URL: " + err.Error()}
		body, _ := json.Marshal(resp)
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetBody(body)
		return
	}

	// Check status code
	statusCode := resp2.StatusCode()
	if statusCode != fasthttp.StatusOK {
		resp := FetchResponse{Error: "unexpected status code: " + fasthttp.StatusMessage(statusCode)}
		body, _ := json.Marshal(resp)
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetBody(body)
		return
	}

	// Parse HTML to extract title and meta description
	bodyBytes := resp2.Body()
	doc, err := goquery.NewDocumentFromReader(strings.NewReader(string(bodyBytes)))
	if err != nil {
		resp := FetchResponse{Error: "failed to parse HTML: " + err.Error()}
		body, _ := json.Marshal(resp)
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetBody(body)
		return
	}

	// Extract title
	title := doc.Find("title").First().Text()
	title = strings.TrimSpace(title)

	// Extract meta description
	description := ""
	doc.Find("meta").Each(func(i int, s *goquery.Selection) {
		if name, exists := s.Attr("name"); exists && strings.ToLower(name) == "description" {
			if content, exists := s.Attr("content"); exists {
				description = strings.TrimSpace(content)
			}
		}
		// Also check property="og:description" for Open Graph
		if property, exists := s.Attr("property"); exists && strings.ToLower(property) == "og:description" {
			if content, exists := s.Attr("content"); exists {
				if description == "" {
					description = strings.TrimSpace(content)
				}
			}
		}
	})

	// Return success response
	resp := FetchResponse{
		Title:       title,
		Description: description,
	}
	body, _ := json.Marshal(resp)
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetBody(body)
}

func main() {
	// Create request handler
	requestHandler := func(ctx *fasthttp.RequestCtx) {
		switch string(ctx.Path()) {
		case "/fetch-preview":
			FetchURLPreview(ctx)
		default:
			ctx.Error("Not Found", fasthttp.StatusNotFound)
		}
	}

	// Start server
	log.Println("Server starting on :8080")
	if err := fasthttp.ListenAndServe(":8080", requestHandler); err != nil {
		log.Fatalf("Error in ListenAndServe: %s", err)
	}
}

