package main

import (
	"encoding/json"
	"log"
	"strings"
	"time"

	"github.com/PuerkitoBio/goquery"
	"github.com/valyala/fasthttp"
)

type URLPreviewRequest struct {
	URL string `json:"url"`
}

type URLPreviewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
	Error       string `json:"error,omitempty"`
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		ctx.SetContentType("application/json")
		ctx.WriteString(`{"error":"method not allowed"}`)
		return
	}

	body := ctx.PostBody()
	var req URLPreviewRequest
	if err := json.Unmarshal(body, &req); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.WriteString(`{"error":"invalid json"}`)
		return
	}

	if req.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.WriteString(`{"error":"url is required"}`)
		return
	}

	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	statusCode, bodyBytes, err := client.Get(nil, req.URL)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		resp := URLPreviewResponse{Error: "failed to fetch url: " + err.Error()}
		data, _ := json.Marshal(resp)
		ctx.Write(data)
		return
	}

	if statusCode != fasthttp.StatusOK {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		resp := URLPreviewResponse{Error: "non-200 status code"}
		data, _ := json.Marshal(resp)
		ctx.Write(data)
		return
	}

	doc, err := goquery.NewDocumentFromReader(strings.NewReader(string(bodyBytes)))
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		resp := URLPreviewResponse{Error: "failed to parse html"}
		data, _ := json.Marshal(resp)
		ctx.Write(data)
		return
	}

	title := doc.Find("title").First().Text()
	description, _ := doc.Find("meta[name=description]").Attr("content")

	resp := URLPreviewResponse{
		Title:       strings.TrimSpace(title),
		Description: strings.TrimSpace(description),
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	data, _ := json.Marshal(resp)
	ctx.Write(data)
}

func main() {
	handler := func(ctx *fasthttp.RequestCtx) {
		switch string(ctx.Path()) {
		case "/fetch-url-preview":
			FetchURLPreview(ctx)
		default:
			ctx.Error("not found", fasthttp.StatusNotFound)
		}
	}

	server := &fasthttp.Server{
		Handler:      handler,
		ReadTimeout:  5 * time.Second,
		WriteTimeout: 5 * time.Second,
	}

	log.Println("Server starting on :8080")
	if err := server.ListenAndServe(":8080"); err != nil {
		log.Fatalf("Error in ListenAndServe: %s", err)
	}
}

