package main

import (
	"encoding/json"
	"log"
	"strings"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
)

// URLPreview represents the extracted preview data from a URL.
type URLPreview struct {
	Title       string `json:"title"`
	Description string `json:"description"`
}

// FetchURLPreview handles POST requests to fetch a URL preview.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only accept POST requests
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		ctx.SetBodyString(`{"error":"method not allowed"}`)
		return
	}

	// Parse JSON body
	var body struct {
		URL string `json:"url"`
	}
	if err := json.Unmarshal(ctx.PostBody(), &body); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBodyString(`{"error":"invalid JSON body"}`)
		return
	}

	if body.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBodyString(`{"error":"url field is required"}`)
		return
	}

	// Create fasthttp client with DialDualStack
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	// Prepare request
	req := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(req)

	req.SetRequestURI(body.URL)
	req.Header.SetMethod(fasthttp.MethodGet)

	// Prepare response
	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(resp)

	// Fetch the URL with redirects
	if err := client.DoRedirects(req, resp, 10); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetBodyString(`{"error":"failed to fetch URL: ` + err.Error() + `"}`)
		return
	}

	// Check status code
	statusCode := resp.StatusCode()
	if statusCode != fasthttp.StatusOK {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetBodyString(`{"error":"upstream returned non-200 status code"}`)
		return
	}

	// Parse HTML to extract title and description
	bodyBytes := resp.Body()
	title, description := parseHTML(bodyBytes)

	// Build response
	preview := URLPreview{
		Title:       title,
		Description: description,
	}

	respJSON, err := json.Marshal(preview)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetBodyString(`{"error":"failed to marshal response"}`)
		return
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	ctx.SetBody(respJSON)
}

// parseHTML extracts the title and meta description from HTML content.
func parseHTML(body []byte) (title string, description string) {
	reader := strings.NewReader(string(body))
	tokenizer := html.NewTokenizer(reader)

	inTitle := false
	for {
		tt := tokenizer.Next()
		switch tt {
		case html.ErrorToken:
			return title, description
		case html.StartTagToken, html.SelfClosingTagToken:
			tagName, hasAttr := tokenizer.TagName()
			tagStr := string(tagName)

			if tagStr == "title" {
				inTitle = true
				continue
			}

			if tagStr == "meta" && hasAttr {
				var name, content string
				for {
					key, val, more := tokenizer.TagAttr()
					attrKey := string(key)
					attrVal := string(val)

					if attrKey == "name" {
						name = attrVal
					}
					if attrKey == "content" {
						content = attrVal
					}
					if !more {
						break
					}
				}
				if name == "description" && description == "" {
					description = content
				}
			}
		case html.TextToken:
			if inTitle {
				title = string(tokenizer.Text())
				inTitle = false
			}
		}
	}
}

