)

type FetchRequest struct {
	URL string `json:"url"`
}

type FetchResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
	Error       string `json:"error,omitempty"`
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Parse request body
	var req FetchRequest
	if err := json.Unmarshal(ctx.PostBody(), &req); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		json.NewEncoder(ctx).Encode(FetchResponse{Error: "Invalid request body"})
		return
	}

	if req.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		json.NewEncoder(ctx).Encode(FetchResponse{Error: "URL is required"})
		return
	}

	// Create fasthttp client with custom settings
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	// Prepare request
	reqHTTP := fasthttp.AcquireRequest()
	respHTTP := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseRequest(reqHTTP)
	defer fasthttp.ReleaseResponse(respHTTP)

	reqHTTP.SetRequestURI(req.URL)
	reqHTTP.Header.SetMethod("GET")

	// Fetch URL with timeout
	err := client.DoRedirects(reqHTTP, respHTTP, 5)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		json.NewEncoder(ctx).Encode(FetchResponse{Error: "Failed to fetch URL: " + err.Error()})
		return
	}

	// Parse HTML
	body := respHTTP.Body()
	doc, err := goquery.NewDocumentFromReader(strings.NewReader(string(body)))
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		json.NewEncoder(ctx).Encode(FetchResponse{Error: "Failed to parse HTML"})
		return
	}

	// Extract title and description
	title := doc.Find("title").First().Text()
	description, _ := doc.Find("meta[name=description]").Attr("content")

	// If description not found, try og:description
	if description == "" {
		description, _ = doc.Find("meta[property='og:description']").Attr("content")
	}

	// Return response
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	json.NewEncoder(ctx).Encode(FetchResponse{
		Title:       strings.TrimSpace(title),
		Description: strings.TrimSpace(description),
	})
}

func main() {
	// Set timeout for the client (3 seconds)
	// Note: The timeout is applied when creating the client in the handler
	// but we can also set it globally here for demonstration
	server := &fasthttp.Server{
		Handler: func(ctx *fasthttp.RequestCtx) {
			switch string(ctx.Path()) {
			case "/fetch-preview":
				FetchURLPreview(ctx)
			default:
				ctx.SetStatusCode(fasthttp.StatusNotFound)
				ctx.SetContentType("application/json")
				json.NewEncoder(ctx).Encode(FetchResponse{Error: "Not found"})
			}
		},
		ReadTimeout:  5 * time.Second,
		WriteTimeout: 5 * time.Second,
	}

	log.Println("Server starting on :8080")
	if err := server.ListenAndServe(":8080"); err != nil {
		log.Fatalf("Error starting server: %v", err)
	}
}

