package main

import (
	"encoding/json"
	"log"
	"net/url"
	"strings"

	"github.com/PuerkitoBio/goquery"
	"github.com/valyala/fasthttp"
)

// FetchURLPreview handles POST requests to fetch and preview a URL.
// It extracts the page title and meta description from the HTML content.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only allow POST method
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		ctx.SetBodyString(`{"error": "Method not allowed"}`)
		return
	}

	// Parse JSON body
	body := ctx.PostBody()
	var req struct {
		URL string `json:"url"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBodyString(`{"error": "Invalid JSON body"}`)
		return
	}

	// Validate URL
	if req.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBodyString(`{"error": "URL is required"}`)
		return
	}

	parsedURL, err := url.ParseRequestURI(req.URL)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBodyString(`{"error": "Invalid URL format"}`)
		return
	}
	if parsedURL.Scheme != "http" && parsedURL.Scheme != "https" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBodyString(`{"error": "URL must start with http or https"}`)
		return
	}

	// Create fasthttp client with DialDualStack
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	// Prepare request
	statusCode, bodyBytes, err := client.Get(nil, req.URL)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetBodyString(`{"error": "Failed to fetch URL: ` + err.Error() + `"}`)
		return
	}

	if statusCode != fasthttp.StatusOK {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetBodyString(`{"error": "URL returned non-200 status code"}`)
		return
	}

	// Parse HTML to extract title and meta description
	title, description := parseHTML(bodyBytes)

	// Prepare response
	resp := struct {
		Title       string `json:"title"`
		Description string `json:"description"`
		URL         string `json:"url"`
	}{
		Title:       title,
		Description: description,
		URL:         req.URL,
	}

	respBytes, err := json.Marshal(resp)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetBodyString(`{"error": "Failed to marshal response"}`)
		return
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	ctx.SetBody(respBytes)
}

// parseHTML extracts the page title and meta description from HTML content.
func parseHTML(htmlBytes []byte) (title, description string) {
	htmlStr := string(htmlBytes)

	doc, err := goquery.NewDocumentFromReader(strings.NewReader(htmlStr))
	if err != nil {
		return "", ""
	}

	// Extract title
	title = strings.TrimSpace(doc.Find("title").First().Text())

	// Extract meta description
	doc.Find("meta").Each(func(i int, s *goquery.Selection) {
		name, _ := s.Attr("name")
		if strings.ToLower(name) == "description" {
			content, exists := s.Attr("content")
			if exists {
				description = strings.TrimSpace(content)
			}
		}
		// Also check for Open Graph description
		property, _ := s.Attr("property")
		if strings.ToLower(property) == "og:description" && description == "" {
			content, exists := s.Attr("content")
			if exists {
				description = strings.TrimSpace(content)
			}
		}
	})

	return title, description
}

func main() {
	// Create router
	m := func(ctx *fasthttp.RequestCtx) {
		switch string(ctx.Path()) {
		case "/fetch-url-preview":
			FetchURLPreview(ctx)
		default:
			ctx.Error("Not Found", fasthttp.StatusNotFound)
		}
	}

	log.Println("Server starting on :8080")
	if err := fasthttp.ListenAndServe(":8080", m); err != nil {
		log.Fatalf("Error in ListenAndServe: %v", err)
	}
}

