// restrictedDial is a custom dial function that prevents connections to private/reserved IPs.
func restrictedDial(addr string) (net.Conn, error) {
	host, _, err := net.SplitHostPort(addr)
	if err != nil {
		host = addr
	}

	if isPrivateOrReserved(host) {
		return nil, fmt.Errorf("connection to private or reserved IP is blocked: %s", host)
	}

	return fasthttp.DialDualStack(addr)
}

// isPrivateOrResolved checks if the given host resolves to a private or reserved IP address.
func isPrivateOrReserved(host string) bool {
	ips, err := net.LookupIP(host)
	if err != nil {
		// If DNS resolution fails, block the request to be safe
		return true
	}

	for _, ip := range ips {
		if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsUnspecified() {
			return true
		}
	}
	return false
}

