	"github.com/valyala/fasthttp"
)

type FetchRequest struct {
	URL string `json:"url"`
}

type FetchResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
	Error       string `json:"error,omitempty"`
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Set response content type
	ctx.SetContentType("application/json")

	// Parse request body
	var req FetchRequest
	body := ctx.PostBody()
	if err := json.Unmarshal(body, &req); err != nil {
		resp := FetchResponse{Error: "Invalid JSON request"}
		data, _ := json.Marshal(resp)
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.Write(data)
		return
	}

	// Validate URL
	if req.URL == "" {
		resp := FetchResponse{Error: "URL is required"}
		data, _ := json.Marshal(resp)
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.Write(data)
		return
	}

	// Create fasthttp client with DialDualStack
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	// Create request
	httpReq := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(httpReq)

	httpReq.SetRequestURI(req.URL)
	httpReq.Header.SetMethod("GET")
	httpReq.Header.Set("User-Agent", "Mozilla/5.0 (compatible; FetchPreview/1.0)")

	// Create response
	httpResp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(httpResp)

	// Fetch URL with redirect handling
	err := client.DoRedirects(httpReq, httpResp, 10)
	if err != nil {
		resp := FetchResponse{Error: "Failed to fetch URL: " + err.Error()}
		data, _ := json.Marshal(resp)
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.Write(data)
		return
	}

	// Check status code
	statusCode := httpResp.StatusCode()
	if statusCode != fasthttp.StatusOK {
		resp := FetchResponse{Error: "Received non-200 status code"}
		data, _ := json.Marshal(resp)
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.Write(data)
		return
	}

	// Parse HTML to extract title and meta description
	htmlBody := string(httpResp.Body())
	doc, err := goquery.NewDocumentFromReader(strings.NewReader(htmlBody))
	if err != nil {
		resp := FetchResponse{Error: "Failed to parse HTML: " + err.Error()}
		data, _ := json.Marshal(resp)
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.Write(data)
		return
	}

	// Extract title
	title := doc.Find("title").First().Text()
	title = strings.TrimSpace(title)

	// Extract meta description
	description := ""
	doc.Find("meta").Each(func(i int, s *goquery.Selection) {
		if name, exists := s.Attr("name"); exists && strings.ToLower(name) == "description" {
			if content, exists := s.Attr("content"); exists {
				description = strings.TrimSpace(content)
			}
		}
	})

	// Return response
	resp := FetchResponse{
		Title:       title,
		Description: description,
	}
	data, err := json.Marshal(resp)
	if err != nil {
		resp := FetchResponse{Error: "Failed to marshal response"}
		data, _ = json.Marshal(resp)
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.Write(data)
		return
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.Write(data)
}

