// isPrivateHost checks if the given hostname resolves to a private/internal IP address.
// This prevents SSRF attacks by blocking access to internal networks.
func isPrivateHost(hostname string) bool {
	// Block common internal hostnames
	lowerHost := strings.ToLower(hostname)
	if lowerHost == "localhost" || strings.HasSuffix(lowerHost, ".local") || strings.HasSuffix(lowerHost, ".internal") {
		return true
	}

	// Resolve the hostname to IP addresses using standard net package
	addrs, err := net.LookupIP(hostname)
	if err != nil {
		// If we can't resolve, block for safety
		return true
	}

	for _, ip := range addrs {
		if ip == nil {
			continue
		}

		// Check for IPv4 private ranges
		if ip4 := ip.To4(); ip4 != nil {
			if ip4[0] == 10 ||
				(ip4[0] == 172 && ip4[1] >= 16 && ip4[1] <= 31) ||
				(ip4[0] == 192 && ip4[1] == 168) ||
				ip4[0] == 127 ||
				(ip4[0] == 169 && ip4[1] == 254) ||
				(ip4[0] == 0) {
				return true
			}
		} else {
			// Check for IPv6 private/loopback/link-local ranges
			if ip.IsLoopback() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsPrivate() {
				return true
			}
		}
	}

	return false
}

