import (
	"encoding/json"
	"log"
	"net/url"
	"strings"

	"github.com/PuerkitoBio/goquery"
	"github.com/valyala/fasthttp"
)

type PreviewRequest struct {
	URL string `json:"url"`
}

type PreviewResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
	Error       string `json:"error,omitempty"`
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only allow POST requests
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"Method not allowed"}`))
		return
	}

	// Parse JSON body
	body := ctx.PostBody()
	var req PreviewRequest
	if err := json.Unmarshal(body, &req); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"Invalid JSON body"}`))
		return
	}

	// Validate URL
	if req.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"URL is required"}`))
		return
	}

	parsedURL, err := url.Parse(req.URL)
	if err != nil || (parsedURL.Scheme != "http" && parsedURL.Scheme != "https") {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"Invalid URL"}`))
		return
	}

	// Create fasthttp client with DialDualStack
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	// Fetch the URL
	statusCode, bodyBytes, err := client.Get(nil, req.URL)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		resp := PreviewResponse{Error: "Failed to fetch URL: " + err.Error()}
		respBytes, _ := json.Marshal(resp)
		ctx.SetBody(respBytes)
		return
	}

	if statusCode != fasthttp.StatusOK {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		resp := PreviewResponse{Error: "URL returned non-200 status code"}
		respBytes, _ := json.Marshal(resp)
		ctx.SetBody(respBytes)
		return
	}

	// Parse HTML using goquery
	doc, err := goquery.NewDocumentFromReader(strings.NewReader(string(bodyBytes)))
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		resp := PreviewResponse{Error: "Failed to parse HTML: " + err.Error()}
		respBytes, _ := json.Marshal(resp)
		ctx.SetBody(respBytes)
		return
	}

	// Extract title
	title := strings.TrimSpace(doc.Find("title").First().Text())

	// Extract meta description
	description := ""
	doc.Find("meta").Each(func(i int, s *goquery.Selection) {
		if name, exists := s.Attr("name"); exists && strings.ToLower(name) == "description" {
			if content, exists := s.Attr("content"); exists {
				description = strings.TrimSpace(content)
			}
		}
	})

	// Return JSON response
	resp := PreviewResponse{
		Title:       title,
		Description: description,
	}

	respBytes, err := json.Marshal(resp)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"Failed to marshal response"}`))
		return
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	ctx.SetBody(respBytes)
}

func main() {
	router := func(ctx *fasthttp.RequestCtx) {
		switch string(ctx.Path()) {
		case "/fetch-preview":
			FetchURLPreview(ctx)
		default:
			ctx.SetStatusCode(fasthttp.StatusNotFound)
			ctx.SetBody([]byte("Not Found"))
		}
	}

	log.Println("Server starting on :8080")
	if err := fasthttp.ListenAndServe(":8080", router); err != nil {
		log.Fatalf("Error in ListenAndServe: %s", err)
	}
}

