// isPrivateOrResolved checks if the hostname resolves to a private or reserved IP address.
func isPrivateOrReserved(host string) bool {
	// Check for raw IP addresses
	ip := net.ParseIP(host)
	if ip != nil {
		return isPrivateIP(ip)
	}

	// Resolve hostname to IP addresses
	ips, err := net.LookupIP(host)
	if err != nil {
		// If resolution fails, block the request for safety
		return true
	}

	for _, resolvedIP := range ips {
		if isPrivateIP(resolvedIP) {
			return true
		}
	}

	return false
}

// isPrivateIP checks if an IP address is private, loopback, link-local, or otherwise reserved.
func isPrivateIP(ip net.IP) bool {
	if ip.IsLoopback() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() || ip.IsPrivate() {
		return true
	}

	// Check for additional reserved ranges
	privateRanges := []string{
		"0.0.0.0/8",
		"100.64.0.0/10",
		"169.254.0.0/16",
		"192.0.0.0/24",
		"192.0.2.0/24",
		"192.88.99.0/24",
		"198.18.0.0/15",
		"198.51.100.0/24",
		"203.0.113.0/24",
		"224.0.0.0/4",
		"240.0.0.0/4",
	}

	for _, cidr := range privateRanges {
		_, subnet, _ := net.ParseCIDR(cidr)
		if subnet.Contains(ip) {
			return true
		}
	}

	return false
}

