package main

import (
	"encoding/json"
	"log"
	"net/url"
	"strings"

	"github.com/valyala/fasthttp"
	"golang.org/x/net/html"
)

// FetchURLPreview handles POST requests to fetch URL preview data.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only allow POST method
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"method not allowed"}`))
		return
	}

	// Parse JSON body
	body := ctx.PostBody()
	var req struct {
		URL string `json:"url"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"invalid json"}`))
		return
	}

	// Validate URL
	if req.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"url is required"}`))
		return
	}

	parsedURL, err := url.Parse(req.URL)
	if err != nil || (parsedURL.Scheme != "http" && parsedURL.Scheme != "https") {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"invalid url"}`))
		return
	}

	// Create fasthttp client with DualStack dial
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	// Prepare request
	fasthttpReq := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(fasthttpReq)
	fasthttpReq.SetRequestURI(req.URL)
	fasthttpReq.Header.SetMethod("GET")
	fasthttpReq.Header.SetUserAgent("Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	// Prepare response
	fasthttpResp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(fasthttpResp)

	// Fetch URL with redirects
	err = client.DoRedirects(fasthttpReq, fasthttpResp, 10)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		respJSON, _ := json.Marshal(map[string]string{"error": "failed to fetch url: " + err.Error()})
		ctx.SetBody(respJSON)
		return
	}

	// Check response status
	statusCode := fasthttpResp.StatusCode()
	if statusCode < 200 || statusCode >= 400 {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		respJSON, _ := json.Marshal(map[string]interface{}{
			"error":      "non-2xx/3xx response",
			"statusCode": statusCode,
		})
		ctx.SetBody(respJSON)
		return
	}

	// Parse HTML to extract title and description
	htmlBody := fasthttpResp.Body()
	title, description := parseHTMLMeta(string(htmlBody))

	// Build response
	result := map[string]interface{}{
		"url":         req.URL,
		"title":       title,
		"description": description,
		"statusCode":  statusCode,
	}

	respJSON, err := json.Marshal(result)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"failed to marshal response"}`))
		return
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	ctx.SetBody(respJSON)
}

// parseHTMLMeta extracts title and meta description from HTML content.
func parseHTMLMeta(htmlContent string) (title, description string) {
	doc, err := html.Parse(strings.NewReader(htmlContent))
	if err != nil {
		return "", ""
	}

	var extract func(*html.Node)
	extract = func(n *html.Node) {
		if n.Type == html.ElementNode {
			if n.Data == "title" {
				if n.FirstChild != nil {
					title = n.FirstChild.Data
				}
			}
			if n.Data == "meta" {
				var name, content string
				for _, attr := range n.Attr {
					if attr.Key == "name" {
						name = strings.ToLower(attr.Val)
					}
					if attr.Key == "content" {
						content = attr.Val
					}
				}
				if name == "description" && description == "" {
					description = content
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			extract(c)
		}
	}

	extract(doc)
	return title, description
}

func main() {
	// Register handler
	fasthttp.ListenAndServe(":8080", func(ctx *fasthttp.RequestCtx) {
		switch string(ctx.Path()) {
		case "/fetch-url-preview":
			FetchURLPreview(ctx)
		default:
			ctx.SetStatusCode(fasthttp.StatusNotFound)
			ctx.SetContentType("application/json")
			ctx.SetBody([]byte(`{"error":"not found"}`))
		}
	})

	log.Println("Server started on :8080")
}

