	}
	return false
}

// isPrivateOrLoopbackIP checks if an IP is private, loopback, or otherwise internal.
func isPrivateOrLoopbackIP(ip net.IP) bool {
	if ip.IsLoopback() || ip.IsPrivate() || ip.IsLinkLocalUnicast() || ip.IsLinkLocalMulticast() {
