func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	if !ctx.IsPost() {
		ctx.Error("Method not allowed", fasthttp.StatusMethodNotAllowed)
		return
	}

	var req struct {
		URL string `json:"url"`
	}

	body := ctx.PostBody()
	if err := json.Unmarshal(body, &req); err != nil {
		ctx.Error("Invalid JSON", fasthttp.StatusBadRequest)
		return
	}

	if req.URL == "" {
		ctx.Error("URL is required", fasthttp.StatusBadRequest)
		return
	}

	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	req2 := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(req2)

	req2.SetRequestURI(req.URL)
	req2.Header.SetMethod("GET")

	resp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(resp)

	deadline := time.Now().Add(3 * time.Second)
	for {
		err := client.DoRedirects(req2, resp, 10)
		if err != nil {
			if netErr, ok := err.(net.Error); ok && netErr.Timeout() {
				ctx.Error("Request timeout", fasthttp.StatusGatewayTimeout)
				return
			}
			ctx.Error("Failed to fetch URL", fasthttp.StatusBadGateway)
			return
		}

		if time.Now().After(deadline) {
			ctx.Error("Request timeout", fasthttp.StatusGatewayTimeout)
			return
		}

		statusCode := resp.StatusCode()
		if statusCode == fasthttp.StatusMovedPermanently ||
			statusCode == fasthttp.StatusFound ||
			statusCode == fasthttp.StatusSeeOther ||
			statusCode == fasthttp.StatusTemporaryRedirect ||
			statusCode == fasthttp.StatusPermanentRedirect {
			location := resp.Header.Peek("Location")
			if len(location) == 0 {
				ctx.Error("Redirect without Location header", fasthttp.StatusBadGateway)
				return
			}
			req2.SetRequestURIBytes(location)
			continue
		}
		break
	}

	bodyBytes := resp.Body()
	title, description := parseHTML(bodyBytes)

	result := struct {
		Title       string `json:"title"`
		Description string `json:"description"`
	}{
		Title:       title,
		Description: description,
	}

	ctx.SetContentType("application/json")
	jsonResp, err := json.Marshal(result)
	if err != nil {
		ctx.Error("Failed to marshal response", fasthttp.StatusInternalServerError)
		return
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.Write(jsonResp)
}

func parseHTML(body []byte) (string, string) {
	doc, err := html.Parse(strings.NewReader(string(body)))
	if err != nil {
		return "", ""
	}

	var title, description string

	var f func(*html.Node)
	f = func(n *html.Node) {
		if n.Type == html.ElementNode {
			if n.Data == "title" {
				if n.FirstChild != nil {
					title = n.FirstChild.Data
				}
			}
			if n.Data == "meta" {
				var name, content string
				for _, attr := range n.Attr {
					if attr.Key == "name" {
						name = attr.Val
					}
					if attr.Key == "content" {
						content = attr.Val
					}
				}
				if name == "description" {
					description = content
				}
			}
		}
		for c := n.FirstChild; c != nil; c = c.NextSibling {
			f(c)
		}
	}
	f(doc)

	return title, description
}

