package main

import (
	"encoding/json"
	"log"
	"net/url"
	"strings"

	"github.com/PuerkitoBio/goquery"
	"github.com/valyala/fasthttp"
)

type FetchRequest struct {
	URL string `json:"url"`
}

type FetchResponse struct {
	Title       string `json:"title"`
	Description string `json:"description"`
	Error       string `json:"error,omitempty"`
}

func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	ctx.SetContentType("application/json")

	var req FetchRequest
	if err := json.Unmarshal(ctx.PostBody(), &req); err != nil {
		resp := FetchResponse{Error: "invalid request body"}
		body, _ := json.Marshal(resp)
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBody(body)
		return
	}

	if req.URL == "" {
		resp := FetchResponse{Error: "url field is required"}
		body, _ := json.Marshal(resp)
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBody(body)
		return
	}

	// Validate URL
	parsedURL, err := url.ParseRequestURI(req.URL)
	if err != nil || (parsedURL.Scheme != "http" && parsedURL.Scheme != "https") {
		resp := FetchResponse{Error: "invalid url"}
		body, _ := json.Marshal(resp)
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBody(body)
		return
	}

	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	statusCode, body, err := client.Get(nil, req.URL)
	if err != nil {
		resp := FetchResponse{Error: "failed to fetch url: " + err.Error()}
		bodyBytes, _ := json.Marshal(resp)
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetBody(bodyBytes)
		return
	}

	if statusCode != fasthttp.StatusOK {
		resp := FetchResponse{Error: "unexpected status code"}
		bodyBytes, _ := json.Marshal(resp)
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetBody(bodyBytes)
		return
	}

	title, description := parseHTML(body)

	resp := FetchResponse{
		Title:       title,
		Description: description,
	}
	respBody, _ := json.Marshal(resp)
	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetBody(respBody)
}

func parseHTML(htmlBody []byte) (string, string) {
	doc, err := goquery.NewDocumentFromReader(strings.NewReader(string(htmlBody)))
	if err != nil {
		return "", ""
	}

	title := doc.Find("title").First().Text()
	title = strings.TrimSpace(title)

	description := ""
	doc.Find("meta").Each(func(i int, s *goquery.Selection) {
		if name, _ := s.Attr("name"); strings.EqualFold(name, "description") {
			desc, _ := s.Attr("content")
			description = strings.TrimSpace(desc)
		}
		if property, _ := s.Attr("property"); strings.EqualFold(property, "og:description") && description == "" {
			desc, _ := s.Attr("content")
			description = strings.TrimSpace(desc)
		}
	})

	return title, description
}

func main() {
	router := func(ctx *fasthttp.RequestCtx) {
		switch string(ctx.Path()) {
		case "/fetch-url-preview":
			if ctx.IsPost() {
				FetchURLPreview(ctx)
			} else {
				ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
				ctx.SetBodyString("Method Not Allowed")
			}
		default:
			ctx.SetStatusCode(fasthttp.StatusNotFound)
			ctx.SetBodyString("Not Found")
		}
	}

	log.Println("Server starting on :8080")
	if err := fasthttp.ListenAndServe(":8080", router); err != nil {
		log.Fatalf("Error in ListenAndServe: %s", err)
	}
}

