func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only allow POST requests
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		ctx.SetBodyString(`{"error": "method not allowed"}`)
		return
	}

	// Parse JSON body
	var request struct {
		URL string `json:"url"`
	}
	body := ctx.PostBody()
	if err := json.Unmarshal(body, &request); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBodyString(`{"error": "invalid JSON body"}`)
		return
	}

	if request.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetBodyString(`{"error": "url field is required"}`)
		return
	}

	// Create fasthttp client with DualStack dial and timeout
	client := &fasthttp.Client{
		Dial:                          fasthttp.DialDualStack,
		ReadTimeout:                   3 * time.Second,
		WriteTimeout:                  3 * time.Second,
		MaxIdemponentCallAttempts:     1,
	}

	// Fetch the URL with redirects
	statusCode, bodyBytes, err := client.Get(nil, request.URL)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		resp := map[string]string{"error": "failed to fetch URL: " + err.Error()}
		respBytes, _ := json.Marshal(resp)
		ctx.SetBody(respBytes)
		return
	}

	if statusCode != fasthttp.StatusOK {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		resp := map[string]string{"error": "URL returned non-200 status"}
		respBytes, _ := json.Marshal(resp)
		ctx.SetBody(respBytes)
		return
	}

	// Parse HTML to extract title and meta description
	htmlContent := string(bodyBytes)
	doc, err := goquery.NewDocumentFromReader(strings.NewReader(htmlContent))
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		resp := map[string]string{"error": "failed to parse HTML"}
		respBytes, _ := json.Marshal(resp)
		ctx.SetBody(respBytes)
		return
	}

	title := doc.Find("title").First().Text()
	description := ""
	doc.Find("meta").Each(func(i int, s *goquery.Selection) {
		if name, exists := s.Attr("name"); exists && strings.ToLower(name) == "description" {
			if content, exists := s.Attr("content"); exists {
				description = content
			}
		}
	})

	// Return JSON response
	response := map[string]string{
		"title":       title,
		"description": description,
	}

	respBytes, err := json.Marshal(response)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetBodyString(`{"error": "failed to marshal response"}`)
		return
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	ctx.SetBody(respBytes)
}

func main() {
	// Register the handler
	requestHandler := func(ctx *fasthttp.RequestCtx) {
		switch string(ctx.Path()) {
		case "/fetch-preview":
			FetchURLPreview(ctx)
		default:
			ctx.Error("not found", fasthttp.StatusNotFound)
		}
	}

	server := &fasthttp.Server{
		Handler: requestHandler,
		Name:    "URL Preview Server",
	}

	log.Println("Server starting on :8080")
	if err := server.ListenAndServe(":8080"); err != nil {
		log.Fatalf("Error in ListenAndServe: %s", err)
	}
}

