// FetchURLPreview handles POST requests to fetch and parse URL previews.
func FetchURLPreview(ctx *fasthttp.RequestCtx) {
	// Only allow POST method
	if !ctx.IsPost() {
		ctx.SetStatusCode(fasthttp.StatusMethodNotAllowed)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"method not allowed"}`))
		return
	}

	// Parse request body
	body := ctx.PostBody()
	var req struct {
		URL string `json:"url"`
	}
	if err := json.Unmarshal(body, &req); err != nil {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"invalid JSON"}`))
		return
	}

	// Validate URL
	if req.URL == "" {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"url is required"}`))
		return
	}

	// Parse URL to ensure it's valid
	parsedURL, err := url.Parse(req.URL)
	if err != nil || (parsedURL.Scheme != "http" && parsedURL.Scheme != "https") {
		ctx.SetStatusCode(fasthttp.StatusBadRequest)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"invalid URL"}`))
		return
	}

	// Create fasthttp client with DualStack dialing
	client := &fasthttp.Client{
		Dial: fasthttp.DialDualStack,
	}

	// Prepare request
	httpReq := fasthttp.AcquireRequest()
	defer fasthttp.ReleaseRequest(httpReq)
	httpReq.SetRequestURI(req.URL)
	httpReq.Header.SetMethod("GET")
	httpReq.Header.Set("User-Agent", "Mozilla/5.0 (compatible; URLPreviewBot/1.0)")

	// Prepare response
	httpResp := fasthttp.AcquireResponse()
	defer fasthttp.ReleaseResponse(httpResp)

	// Fetch URL with redirect handling
	err = client.DoRedirects(httpReq, httpResp, 10)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		resp := map[string]interface{}{
			"error": "failed to fetch URL: " + err.Error(),
		}
		respBytes, _ := json.Marshal(resp)
		ctx.SetBody(respBytes)
		return
	}

	statusCode := httpResp.StatusCode()
	bodyBytes := httpResp.Body()

	// Check HTTP status code
	if statusCode >= 400 {
		ctx.SetStatusCode(fasthttp.StatusBadGateway)
		ctx.SetContentType("application/json")
		resp := map[string]interface{}{
			"error":      "URL returned non-OK status",
			"statusCode": statusCode,
		}
		respBytes, _ := json.Marshal(resp)
		ctx.SetBody(respBytes)
		return
	}

	// Parse HTML to extract title and meta description
	title := ""
	description := ""

	// Use goquery to parse the HTML
	doc, err := goquery.NewDocumentFromReader(strings.NewReader(string(bodyBytes)))
	if err == nil {
		// Extract title
		title = doc.Find("title").First().Text()
		title = strings.TrimSpace(title)

		// Extract meta description
		doc.Find("meta").Each(func(i int, s *goquery.Selection) {
			name, _ := s.Attr("name")
			property, _ := s.Attr("property")
			content, _ := s.Attr("content")

			if strings.ToLower(name) == "description" && description == "" {
				description = content
			}
			if strings.ToLower(property) == "og:description" && description == "" {
				description = content
			}
		})
		description = strings.TrimSpace(description)
	}

	// If goquery fails, try simple string parsing as fallback
	if title == "" {
		bodyStr := string(bodyBytes)
		title = extractBetween(bodyStr, "<title>", "</title>")
		title = strings.TrimSpace(title)
	}

	if description == "" {
		bodyStr := string(bodyBytes)
		// Try to find meta description
		desc := extractMetaContent(bodyStr, "description")
		if desc == "" {
			desc = extractMetaContent(bodyStr, "og:description")
		}
		description = strings.TrimSpace(desc)
	}

	// Prepare response
	response := map[string]interface{}{
		"url":         req.URL,
		"title":       title,
		"description": description,
		"statusCode":  statusCode,
	}

	respBytes, err := json.Marshal(response)
	if err != nil {
		ctx.SetStatusCode(fasthttp.StatusInternalServerError)
		ctx.SetContentType("application/json")
		ctx.SetBody([]byte(`{"error":"failed to marshal response"}`))
		return
	}

	ctx.SetStatusCode(fasthttp.StatusOK)
	ctx.SetContentType("application/json")
	ctx.SetBody(respBytes)
}

// extractBetween extracts text between two strings
func extractBetween(s, start, end string) string {
	startIdx := strings.Index(strings.ToLower(s), strings.ToLower(start))
	if startIdx == -1 {
		return ""
	}
	startIdx += len(start)
	endIdx := strings.Index(strings.ToLower(s[startIdx:]), strings.ToLower(end))
	if endIdx == -1 {
		return ""
	}
	return s[startIdx : startIdx+endIdx]
}

// extractMetaContent extracts content from a meta tag
func extractMetaContent(s, name string) string {
	lower := strings.ToLower(s)
	// Look for name="description" or property="og:description"
	patterns := []string{
		`name="` + name + `"`,
		`name='` + name + `'`,
		`property="` + name + `"`,
		`property='` + name + `'`,
	}

	for _, pattern := range patterns {
		idx := strings.Index(lower, pattern)
		if idx != -1 {
			// Find content attribute
			remaining := lower[idx+len(pattern):]
			contentIdx := strings.Index(remaining, "content=")
			if contentIdx != -1 {
				contentStart := remaining[contentIdx+8:] // skip 'content="'
				// Check for quote type
				if len(contentStart) > 0 {
					quote := contentStart[0]
					if quote == '"' || quote == '\'' {
						contentStart = contentStart[1:]
						endQuote := strings.IndexByte(contentStart, quote)
						if endQuote != -1 {
							return contentStart[:endQuote]
						}
					}
				}
			}
		}
	}
	return ""
}

func main() {
	// Create request handler
	handler := func(ctx *fasthttp.RequestCtx) {
		switch string(ctx.Path()) {
		case "/fetch-url-preview":
			FetchURLPreview(ctx)
		default:
			ctx.SetStatusCode(fasthttp.StatusNotFound)
			ctx.SetContentType("application/json")
			ctx.SetBody([]byte(`{"error":"not found"}`))
		}
	}

	// Start server
	log.Println("Server starting on :8080")
	if err := fasthttp.ListenAndServe(":8080", handler); err != nil {
		log.Fatalf("Error in ListenAndServe: %v", err)
	}
}

